package com.example.complaintmanagement.mapper; import com.example.complaintmanagement.entity.*; import com.example.complaintmanagement.dto.ComplaintDtos.*; public class CommentMapper { public CommentResponse toResponse(Comment c){return new CommentResponse(c.getId(),c.getUser().getUsername(),c.getMessage(),c.getCreatedAt().toString());} public ActivityResponse activity(ComplaintActivity a){return new ActivityResponse(a.getId(),a.getPerformedBy().getUsername(),a.getActivityType(),a.getDescription(),a.getCreatedAt().toString());} }